import{p as Q,M as X,c as j,r as _,w as E,G as Z,d as t,e as s,g as a,F as u,i as ee,l as te,j as ne,f as w,t as c,h as g,q as v,m as ae,I as oe,o as n,k as b,N as se,S as ie}from"./index-4c9238bd.js";import{wordPhonetics as re}from"./wordPhonetics-36723ad7.js";const H="2026-10-19",P=[{title:"A Quiet Hall in the Forbidden City",basedOn:[],source:"ad-hoc-news.de（故宫博物院公告）",passage:`The Palace Museum in Beijing announced that Wuying Hall, one of the historic buildings in the Forbidden City, will close to visitors starting October 19, 2026. The museum did not say when the hall will open again.

Wuying Hall, which means "Hall of Military Prowess," was built hundreds of years ago during the Ming Dynasty. It is part of the Imperial Palaces of the Ming and Qing Dynasties, a site on UNESCO's World Heritage List since 1987.

The museum said the closure is for the protection of the old building, the care of its collections, and the improvement of its displays. Workers will repair the wooden structure and update the exhibition inside the hall.

Visitors can still visit other parts of the Forbidden City. The museum advises travelers to check the latest notices before their trip, as some halls may have different opening hours.

The Forbidden City was built between 1406 and 1420 and was home to 24 emperors. Today it is one of the most visited museums in the world, welcoming millions of visitors every year.`,notes:[{word:"palace",pos:"n.",meaning:"宫殿"},{word:"dynasty",pos:"n.",meaning:"朝代"},{word:"heritage",pos:"n.",meaning:"遗产"},{word:"emperor",pos:"n.",meaning:"皇帝"},{word:"collection",pos:"n.",meaning:"收藏品"},{word:"exhibition",pos:"n.",meaning:"展览"},{word:"repair",pos:"v.",meaning:"修理"},{word:"structure",pos:"n.",meaning:"结构"}],questions:[{q:"Why will Wuying Hall close?",options:["To protect the old building and improve its displays","To build a new shopping mall","Because few people visit it","To make a movie"],answer:0},{q:"When was the Forbidden City built?",options:["1406–1420","1906–1920","1987–1997","2008–2018"],answer:0},{q:"Can visitors still visit the Forbidden City?",options:["Yes, other parts remain open","No, the whole palace is closed","Only at night","Only with an emperor"],answer:0}]},{title:"Typhoon Season: Staying Safe in Strong Winds",basedOn:[],source:"中廣新聞網《10分鐘早報》(YouTube)",passage:`October is typhoon season in East Asia. This week, a strong typhoon is moving toward Taiwan, bringing heavy rain and powerful winds. Weather experts say people should prepare for the storm during the holiday.

A typhoon is a huge storm that forms over warm ocean water. When it reaches land, it can break trees, damage houses, and cause floods. In the past, strong typhoons have forced schools to close and flights to stop.

To stay safe, experts give some simple advice. First, keep enough food and drinking water at home for two or three days. Second, stay away from windows during the storm, and do not go outside when the wind is strong. Third, charge your phone and flashlight before the power goes out.

After the typhoon passes, be careful of fallen trees and broken electric wires on the road. Do not touch the wires; call the police or the power company instead.

Typhoons are a natural part of life in this region. With good preparation, people can stay safe and return to normal life quickly.`,notes:[{word:"typhoon",pos:"n.",meaning:"台风"},{word:"expert",pos:"n.",meaning:"专家"},{word:"flood",pos:"n.",meaning:"洪水"},{word:"prepare",pos:"v.",meaning:"准备"},{word:"flashlight",pos:"n.",meaning:"手电筒"},{word:"wire",pos:"n.",meaning:"电线；金属丝"},{word:"region",pos:"n.",meaning:"地区"}],questions:[{q:"What should people keep at home before a typhoon?",options:["Enough food and drinking water","Fireworks and candles only","A new car","Many books"],answer:0},{q:"What should you NOT do during the storm?",options:["Charge your phone","Stay away from windows","Go outside when the wind is strong","Keep food at home"],answer:2},{q:"What should you do if you see broken electric wires?",options:["Touch them to check","Do not touch them; call the police or power company","Take them home","Ignore them and walk on"],answer:1}]},{title:"AI Takes the Stage in Berlin",basedOn:[],source:"21经济网《财经日历》",passage:`This week, the world's attention turns to Berlin, Germany, where chip company NVIDIA holds its GTC technology conference. Company leader Jensen Huang will give an important speech on October 21.

NVIDIA is famous for making the powerful chips that train artificial intelligence (AI). These chips help computers learn languages, recognize pictures, and even drive cars. In recent years, the need for AI chips has grown very fast around the world.

At the Berlin event, the company is expected to share its newest chip designs and talk about working with German companies on AI computing power. Germany's leader is also expected to meet Huang to discuss how the two sides can work together.

AI technology is changing many jobs and daily life. From hospitals to factories, more places are using AI to work faster and better. But experts also warn that countries need to think carefully about how to use AI safely.

For students learning English today, AI is not just news — it may become part of their future work.`,notes:[{word:"conference",pos:"n.",meaning:"会议；大会"},{word:"chip",pos:"n.",meaning:"芯片"},{word:"artificial intelligence",pos:"n.",meaning:"人工智能"},{word:"recognize",pos:"v.",meaning:"认出；识别"},{word:"computing power",pos:"n.",meaning:"算力"},{word:"discuss",pos:"v.",meaning:"讨论"},{word:"warn",pos:"v.",meaning:"警告"}],questions:[{q:"What is NVIDIA famous for?",options:["Making powerful chips for AI","Selling clothes","Building houses","Growing food"],answer:0},{q:"When will Jensen Huang give his speech?",options:["October 21","October 1","November 21","December 25"],answer:0},{q:"What do experts warn about?",options:["Countries need to use AI carefully and safely","AI will disappear soon","Chips are too cheap","Berlin is too cold"],answer:0}]}],le={date:H,newsReadings:P},de=Object.freeze(Object.defineProperty({__proto__:null,date:H,default:le,newsReadings:P},Symbol.toStringTag,{value:"Module"})),z="2026-10-20",D=[{notes:[{meaning:"超声波",pos:"n.",word:"ultrasound"},{meaning:"毫无防御能力的",pos:"adj.",word:"defenceless"},{meaning:"拦截；截获",pos:"v.",word:"intercept"},{meaning:"对策；反制措施",pos:"n.",word:"countermeasure"},{meaning:"消散；耗散",pos:"v.",word:"dissipate"},{meaning:"阈值；门槛；开端",pos:"n.",word:"threshold"},{meaning:"原型；样机",pos:"n.",word:"prototype"},{meaning:"城市化",pos:"n.",word:"urbanisation"},{meaning:"残留物",pos:"n.",word:"residue"},{meaning:"心血管的",pos:"adj.",word:"cardiovascular"},{meaning:"对（旧建筑/设备）翻新改造",pos:"v.",word:"retrofit"},{meaning:"笨重的；难以处理的",pos:"adj.",word:"cumbersome"},{meaning:"仿效；模拟",pos:"v.",word:"emulate"},{meaning:"原则上；理论上",pos:"adv.",word:"in principle"}],passage:`On a summer night, an apparently defenceless moth flutters through the darkness, pursued by one of nature's most accomplished hunters. The bat need not see its prey; it listens. By emitting rapid pulses of ultrasound and interpreting the echoes that bounce back, it constructs an acoustic map of the world accurate enough to intercept an insect in mid-flight. For the moth, this should be a death sentence. Yet millions of years of evolution have equipped certain species with an extraordinary countermeasure: wings that do not merely fail to reflect sound, but actively absorb it.

The secret lies in structures invisible to the naked eye. The wing surfaces of moths such as the Chinese oak silkmoth are covered in a dense carpet of microscopic scales, each shaped to dissipate acoustic energy rather than return it to the bat. Acting, in effect, as an invisibility cloak against sonar, these formations reduce the strength of the echo reaching the predator, shrinking the distance at which the moth can be detected. What natural selection refined for survival is now being re-examined by engineers for an altogether different purpose.

That re-examination is the work of Professor Marc Holderied and his colleagues at the University of Bristol's School of Biological Sciences, who have spent years unravelling the physics of moth-wing acoustics. Their research has now crossed the threshold from laboratory curiosity to commercial prospect: a spinout company, Attacus Acoustics, announced in October 2026 that it will develop and market a new generation of ultra-lightweight sound-absorbing materials derived from these biological principles. Early prototypes suggest that the moth-inspired structures can deliver effective sound absorption in layers up to ten times thinner than many conventional materials — a step change in an industry where performance has historically depended on bulk.

The timing is significant, because the problem this technology promises to address is among the fastest-growing environmental and public health challenges of the modern city: noise pollution. Unlike smog, noise leaves no visible residue, yet its effects are increasingly well documented. The World Health Organization has linked long-term exposure to excessive noise with chronic stress, disrupted sleep, cardiovascular disease and a measurable decline in overall wellbeing. As urbanisation intensifies and transport networks expand, ever larger populations find themselves living and working in acoustic environments for which the human body was never designed.

Existing remedies are conspicuously inadequate. Traditional soundproofing relies on mass: thick layers of mineral wool, dense foams or heavy composite panels whose bulk makes them difficult to install in aircraft cabins, vehicles and retrofitted buildings, where every kilogram and every centimetre matters. Such materials are, moreover, frequently resource-intensive to manufacture and cumbersome to dispose of. The resulting demand for lighter, more efficient and more sustainable alternatives has been growing for years — but engineering advances have tended to deliver only marginal improvements.

This is what makes the Bristol approach more than an ingenious laboratory trick. Biomimicry — the practice of solving human problems by emulating nature's designs — has already produced self-cleaning surfaces inspired by the lotus leaf and a quieter bullet train whose nose mimics the beak of the kingfisher. The moth wing, however, offers something rarer: a solution that did not evolve under human constraints, yet outperforms the products of deliberate engineering. Its absorption mechanism depends not on weight but on geometry, meaning that performance can, in principle, be scaled without the usual penalty in mass or thickness.

Considerable obstacles remain before Attacus Acoustics' materials line the walls of hospitals, recording studios or high-speed trains. Reproducing the moth's intricate microstructures at industrial scale will require advances in manufacturing, and the economics of production have yet to be proven. Nevertheless, the direction of travel is clear. If an insect's ancient battle against the bat can teach us how to build quieter cities, it will be a striking reminder that some of the most sophisticated technologies on Earth were patented, so to speak, long before humans arrived.`,questions:[{answer:1,options:["By detecting the moths' body heat","By emitting ultrasound and analysing the returning echoes","By following the scent trails left by moths","By sensing vibrations in the air with their wings"],q:"According to the passage, how do hunting bats locate moths in darkness?"},{answer:1,options:["the moth's ability to fly completely silently","wing structures that absorb rather than reflect sound","a new type of military radar system","the darkness in which moths fly"],q:'The phrase "invisibility cloak against sonar" (paragraph 2) is used to describe'},{answer:2,options:["chronic stress","cardiovascular disease","improved concentration","disrupted sleep"],q:"According to paragraph 4, long-term exposure to excessive noise is associated with all of the following EXCEPT"},{answer:1,options:["It is cheaper to manufacture","It performs well despite being much thinner","It requires no maintenance at all","It works only at very low frequencies"],q:"What advantage does the moth-inspired material offer over conventional soundproofing?"},{answer:1,options:["True","False","Not Given"],q:"Attacus Acoustics was founded by researchers from the University of Cambridge."},{answer:0,options:["True","False","Not Given"],q:"Conventional soundproofing materials are described as heavy, bulky and resource-intensive to produce."},{answer:1,options:["True","False","Not Given"],q:"The passage states that Attacus Acoustics' materials are already installed in hospitals and recording studios."}],source:"University of Bristol (press release, 6 October 2026)",title:"The Moth's Secret: How a Nocturnal Insect Could Transform Soundproofing"},{notes:[{meaning:"隐喻；比喻",pos:"n.",word:"metaphor"},{meaning:"支撑；构成……的基础",pos:"v.",word:"underpin"},{meaning:"引人注目的；惊人的",pos:"adj.",word:"arresting"},{meaning:"占主导地位",pos:"v.",word:"predominate"},{meaning:"（对说法）加以限定；修正",pos:"v.",word:"qualify"},{meaning:"增强；增加",pos:"v.",word:"augment"},{meaning:"彻底地；完全地",pos:"adv.",word:"outright"},{meaning:"细微差别",pos:"n.",word:"nuance"},{meaning:"惨淡的；无望的",pos:"adj.",word:"bleak"},{meaning:"补充；互补（物）",pos:"n./v.",word:"complement"},{meaning:"替代品；替代",pos:"n./v.",word:"substitute"},{meaning:"（员工）自然减员",pos:"n.",word:"attrition"},{meaning:"裁决；定论",pos:"n.",word:"verdict"},{meaning:"不成比例地",pos:"adv.",word:"disproportionately"}],passage:`When Kristalina Georgieva, the managing director of the International Monetary Fund, addressed the institution's annual meetings in Bangkok on 12 October 2026, she chose a deliberately vivid metaphor. Artificial intelligence, she said, is a "slow-moving tsunami" for the world's labour markets — a force whose disruptive potential is inseparable from its power to sustain. The same technology now underpinning global growth, she argued, may simultaneously reshape who gets paid to work.

The headline figure was arresting: around 40 per cent of jobs worldwide could be affected by AI. In advanced economies, where white-collar work predominates, the share rises to roughly 60 per cent; in lower-income countries, where manual and agricultural labour remain dominant, it falls to between 23 and 26 per cent. Yet Georgieva was careful to qualify the statistic. "Affected", in the IMF's vocabulary, encompasses three distinct fates: jobs that AI augments, making workers more productive; jobs it downgrades, eroding wages or skill requirements; and jobs it eliminates outright. Exposure, she emphasised, is not synonymous with extinction.

That nuance matters, because the technology is simultaneously propping up the economy it threatens to disrupt. Heavy investment in AI infrastructure — the data centres, semiconductors and energy capacity required to train and run large models — is, in Georgieva's assessment, one of the principal reasons global growth is holding at around 3 per cent in 2026. The IMF estimates that such spending is adding between half and one percentage point to growth in advanced Asian economies, and between 0.2 and 0.8 points in emerging Asia. The United States, China and India have emerged as the leading producers of AI systems, while other Asian economies supply the physical backbone of chips and hardware.

Evidence of the labour-market impact is accumulating in the data. The IMF's October 2026 Regional Economic Outlook for Asia and the Pacific, drawing on approximately 40 million online job postings across 19 economies, found that employer demand has fallen by nearly 10 per cent in occupations more exposed to AI, relative to less-exposed roles, since the launch of ChatGPT in November 2022. Notably, however, the decline appears to have stabilised. One reason is the emergence of entirely new categories of work: employers increasingly seek specialists in prompt engineering, retrieval-augmented generation and the development of AI agents — roles that scarcely existed five years ago.

Nor is the picture uniformly bleak. Only about 6 per cent of Asian firms explicitly request AI skills in their job advertisements, suggesting that adoption remains uneven. More strikingly, businesses that have adopted AI are experiencing stronger labour-demand growth than those that have not — including in occupations highly exposed to automation. The implication is that, at the level of the individual firm, AI often functions as a complement to human labour rather than a substitute: it absorbs routine tasks while increasing the value of workers who can direct, supervise and integrate the technology.

Against this qualified optimism, however, stands a new and less ambiguous signal from the United States. The Federal Reserve's Beige Book, published on 14 October 2026, documented for the first time that firms in five of its twelve districts had reduced staffing levels through attrition, delayed hiring or planned fewer future hires after raising productivity with AI. Because the Beige Book is compiled from conversations with business contacts, it captures decisions before they appear in payroll statistics — making it an early warning rather than a verdict. Official data still looks comparatively firm: initial claims for unemployment benefits stood at 197,000 in early October, although the unemployment rate edged up to 4.2 per cent in September.

What emerges from these overlapping reports is a labour market in transition rather than in free fall. The historical record suggests that general-purpose technologies — from the steam engine to the computer — ultimately create more work than they destroy, but the adjustment is rarely painless, and its costs fall disproportionately on workers least equipped to adapt. The IMF's warning is therefore less a prediction of mass unemployment than a call for preparation: in skills development, in social safety nets, and in the deliberate design of AI systems that amplify rather than replace human capability. Whether the coming years bring augmentation or displacement will depend less on the technology itself than on the choices made around it.`,questions:[{answer:1,options:["A double-edged sword","A slow-moving tsunami","A perfect storm","A rising tide"],q:"What metaphor did Georgieva use to describe AI's impact on labour markets?"},{answer:2,options:["23 per cent","40 per cent","60 per cent","80 per cent"],q:"According to the IMF, in advanced economies the share of jobs that could be affected by AI is approximately"},{answer:0,options:["fallen by nearly 10 per cent relative to less-exposed occupations","doubled compared with less-exposed occupations","remained completely unchanged","risen faster than in any other sector"],q:"The IMF study of Asian job postings found that since November 2022, demand in AI-exposed occupations has"},{answer:1,options:["have laid off most of their workforce","are experiencing stronger labour-demand growth than non-adopters","no longer advertise for any staff","request AI skills in all of their job postings"],q:"According to paragraph 5, firms that have adopted AI"},{answer:1,options:["True","False","Not Given"],q:"The US Federal Reserve's Beige Book reported that companies in all twelve districts had cut staff because of AI."},{answer:0,options:["True","False","Not Given"],q:"The passage suggests that AI investment is contributing to global economic growth of around 3 per cent in 2026."},{answer:1,options:["True","False","Not Given"],q:"Official US unemployment data in early October 2026 confirmed a sharp rise in joblessness."}],source:"Reuters (IMF–World Bank Annual Meetings, Bangkok, 12 October 2026)",title:"Forty Percent: Artificial Intelligence and the Future of Employment"},{notes:[{meaning:"难以想象的",pos:"adj.",word:"inconceivable"},{meaning:"灾难；巨变",pos:"n.",word:"catastrophe"},{meaning:"冰川学家",pos:"n.",word:"glaciologist"},{meaning:"波动；起伏",pos:"n.",word:"fluctuation"},{meaning:"贫乏的；不足的",pos:"adj.",word:"meagre"},{meaning:"自我强化的",pos:"adj.",word:"self-reinforcing"},{meaning:"象征性的；典型的",pos:"adj.",word:"emblematic"},{meaning:"壮丽；宏伟",pos:"n.",word:"grandeur"},{meaning:"异常；反常现象",pos:"n.",word:"anomaly"},{meaning:"水库；蓄水池；储库",pos:"n.",word:"reservoir"},{meaning:"水力发电",pos:"n.",word:"hydropower"},{meaning:"轨迹；发展趋势",pos:"n.",word:"trajectory"},{meaning:"排放（物）",pos:"n.",word:"emissions"},{meaning:"矛盾的；似非而是的",pos:"adj.",word:"paradoxical"}],passage:`High in the Swiss Alps, the Aletsch Glacier — the largest river of ice in the Alps and a UNESCO World Heritage site — is undergoing a transformation that would have been inconceivable to the generations who first mapped it. In 2026, this ancient mass of ice suffered its greatest melt in recorded history, part of a national catastrophe: Switzerland's glaciers lost more than five per cent of their total ice volume in a single year, according to a report published on 1 October by the Swiss Glacier Monitoring Network (GLAMOS) and the Swiss Commission for Cryosphere Observation.

The figures, stark in isolation, become more alarming in context. Over the past five years, Swiss glaciers have shed almost a fifth of their ice — a rate of loss that glaciologists describe as a fundamental shift rather than a temporary fluctuation. "Now we are in this new world, in this future, where glaciers are just melting away," said Matthias Huss, the director of GLAMOS. The combination responsible for 2026's devastation was brutally simple: a winter that delivered too little snow, followed by a summer of record-breaking heat.

The mechanics of the disaster are well understood. Fresh winter snow normally acts as a reflective shield, bouncing solar radiation back into the atmosphere and insulating the older ice beneath. When snowfall is meagre, that protection vanishes early in the season, exposing dark, ancient ice that absorbs rather than reflects heat. What follows is a self-reinforcing cycle: the darker the surface, the more solar energy it absorbs, and the faster it melts. In 2026, this feedback loop operated almost without interruption from July to September, a period in which Swiss glaciers released an estimated 2.2 trillion litres of water — more than four times the annual drinking-water consumption of Swiss households.

The damage was not evenly distributed. The Aletsch, emblematic of Alpine grandeur, recorded its largest annual loss ever measured. The Glacier de Tsanfleuron offered the most dramatic illustration of thinning: it lost more than four metres of average thickness, a figure Huss described as unthinkable only a few years ago. Even so, 2026 did not quite eclipse the record set in 2022, when dust clouds drifting north from the Sahara settled on the snow, darkening it and supercharging the melt. That the current year ranks among the worst despite the absence of such an anomaly is, for scientists, the more troubling fact.

"We are seeing extreme years almost every year now, and this is really a worrying situation," Huss told reporters. His concern extends beyond the aesthetic loss of an iconic landscape. Glaciers function as natural reservoirs, storing winter precipitation and releasing it gradually through the dry summer months — a service on which agriculture, hydropower and drinking-water supplies across the Alpine region depend. Their retreat therefore poses a slow-burning threat to water security, even as the immediate surplus of meltwater temporarily eases summer shortages. Switzerland derives the majority of its electricity from hydropower, making the long-term reliability of glacial runoff a matter of national economic significance.

The scientific community is increasingly blunt about the trajectory. Modelling studies suggest that even under optimistic emissions scenarios, a large proportion of Alpine glaciers will disappear within decades; under current trends, some researchers warn, the great ice fields could be reduced to fragments by the end of the century. Water managers are already redesigning reservoirs to cope with a future in which the summer melt they once relied upon can no longer be taken for granted, while mountain communities confront the unsettling question of what their valleys will look like — and what they will be worth — without their glaciers.

Yet the glaciers retain a paradoxical power: as monuments to loss, they have become among the most persuasive communicators of climate change. Satellite images of the retreating Aletsch circulate globally each autumn, translating abstract temperature curves into visible absence. Whether that visibility will translate into the emissions reductions required to slow the melt remains, for Huss and his colleagues, an open — and increasingly urgent — question.`,questions:[{answer:1,options:["less than one per cent of their ice","more than five per cent of their ice","almost a fifth of their ice in a single year","exactly the same amount as in 2022"],q:"According to the GLAMOS report, in 2026 Swiss glaciers lost"},{answer:1,options:["It reduced rainfall in the valleys below","It exposed darker ice that absorbs more heat","It caused more tourists to visit the glaciers","It lowered the temperature of the surrounding air"],q:"Why did the lack of winter snow make the melting worse?"},{answer:1,options:["The Aletsch Glacier","The Glacier de Tsanfleuron","The Rhône Glacier","The Morteratsch Glacier"],q:"Which glacier lost more than four metres of average thickness in 2026?"},{answer:1,options:["attract large numbers of tourists to Switzerland","store winter precipitation and release it gradually in summer","generate heat for nearby villages","prevent earthquakes in the Alps"],q:"According to paragraph 5, glaciers are important because they"},{answer:1,options:["True","False","Not Given"],q:"The year 2026 set a new all-time record for Swiss glacier melt, surpassing 2022."},{answer:0,options:["True","False","Not Given"],q:"Matthias Huss believes the rapid glacier retreat is a worrying situation."},{answer:0,options:["True","False","Not Given"],q:"The report states that glacier meltwater has helped ease summer water shortages."}],source:"Reuters (1 October 2026)",title:"When Ice Becomes Memory: Switzerland's Disappearing Glaciers"}],ce={date:z,newsReadings:D},he=Object.freeze(Object.defineProperty({__proto__:null,date:z,default:ce,newsReadings:D},Symbol.toStringTag,{value:"Module"})),L="2026-10-21",U=[{notes:[{meaning:"痕迹；微量的",pos:"n./adj.",word:"trace"},{meaning:"顽固的；难以解决的",pos:"adj.",word:"stubborn"},{meaning:"混合；交融",pos:"v.",word:"mingle"},{meaning:"嗅觉的",pos:"adj.",word:"olfactory"},{meaning:"有辨别力的；敏锐的",pos:"adj.",word:"discerning"},{meaning:"有气味的物质",pos:"n.",word:"odorant"},{meaning:"等离子体（激元）的",pos:"adj.",word:"plasmonic"},{meaning:"热点；高度活跃区",pos:"n.",word:"hotspot"},{meaning:"指纹；特征标识",pos:"n.",word:"fingerprint"},{meaning:"增强；扩大",pos:"v.",word:"augment"},{meaning:"最先进的",pos:"adj.",word:"state-of-the-art"},{meaning:"选择性",pos:"n.",word:"selectivity"},{meaning:"众所周知地（多指负面）",pos:"adv.",word:"notoriously"},{meaning:"分析的",pos:"adj.",word:"analytical"},{meaning:"广谱的；宽范围的",pos:"adj.",word:"broad-spectrum"},{meaning:"巨大的；难以克服的",pos:"adj.",word:"formidable"},{meaning:"融合",pos:"n.",word:"fusion"},{meaning:"故意的；深思熟虑的",pos:"adj.",word:"deliberate"}],passage:`Detecting trace chemicals in the air — the faint odour of explosives, the invisible leak of a toxic gas, the first molecular whisper of disease — has long been one of technology's most stubborn challenges. Synthetic sensors, for all their precision, struggle in real-world environments where hundreds of compounds mingle and interfere. Evolution, however, has been refining chemical detection for hundreds of millions of years. A team of researchers has now shown that the most powerful sensor may be a hybrid: a living insect, augmented with nanomaterials, that outperforms both biology and machines alone.

The insect in question is the locust, whose antennae are studded with tens of thousands of olfactory receptors capable of discerning minute differences between odorants. Working with Srikanth Singamaneni's laboratory, which specialises in designing and synthesising nanomaterials, and Barani Raman's group, which has spent years mapping the locust's sensory circuits, the researchers attached a specially engineered foam to the insect's antennae. The foam is built from plasmonic nanostructures — metallic architectures that concentrate light into intense electromagnetic hotspots, enabling a technique known as surface-enhanced Raman spectroscopy, or SERS, which can identify individual molecules by their vibrational fingerprints.

The crucial finding was that the foam augmented the locust's odour-detecting abilities without interfering with its other functions. In a series of tests, the hybrid systems successfully detected a wider range of smells than both unmodified locusts and state-of-the-art synthetic chemical sensors. Remarkably, the biohybrid detectors picked up the chemical signature of TNT, the explosive, demonstrating a sensitivity that could have immediate applications in security screening and environmental monitoring.

The collaboration itself illustrates how modern science increasingly advances at the boundaries between disciplines. Singamaneni's laboratory has spent years perfecting the design and synthesis of plasmonic nanostructures, materials whose optical properties can be tuned with extraordinary precision. Raman's team, meanwhile, has devoted equal effort to mapping the neural circuitry that carries signals from the locust's antennae to its brain, work that revealed just how sophisticated the insect's odour-processing machinery already is. Bringing these two lines of enquiry together was not simply a matter of sticking a material onto an insect: the foam had to be engineered to interface with the antenna without obstructing the sensory hairs through which odours reach the receptors. That the researchers succeeded — and that the resulting system outperformed both non-SERS locusts and synthetic sensors across every chemical tested — suggests the approach is robust rather than a laboratory curiosity.

What makes this achievement significant is not merely the raw performance but the way two fundamentally different detection strategies complement each other. The biological component — the locust's antenna — provides exquisite selectivity and the ability to operate in complex, noisy chemical environments, a feat that artificial sensors find notoriously difficult. The nanomaterial component adds a second, independent mode of detection, allowing researchers to confirm and characterise what the insect senses. As Raman observed, the results clearly showed that the best of the two worlds can be merged.

A key challenge in chemical sensing, Raman noted, is that researchers often do not know in advance which molecules they are targeting. A sensor tuned for one compound may be blind to another. The foam attached to the antenna helps identify particular chemical species, adding analytical power to the insect's broad-spectrum awareness. The biology and the chemical sensing parts complement each other: where the locust detects that something is present, the plasmonic foam helps determine precisely what it is.

The implications extend well beyond the laboratory. Biohybrid sensors of this kind could one day be deployed for detecting explosives at checkpoints, monitoring industrial emissions, or even diagnosing disease from breath samples — all tasks where detecting minute chemical traces reliably and inexpensively remains a formidable obstacle. The research, published in the journal Advanced Materials under the title "Plasmonic Foam-Enabled Dual-Modal Biohybrid Chemical Sensor," suggests that the future of sensing may lie not in choosing between nature and engineering, but in the deliberate fusion of the two.`,questions:[{answer:1,options:["They can detect only one specific chemical at a time.","They operate well in complex environments with many mixed compounds.","They are cheaper to manufacture than synthetic sensors.","They can identify molecules without any assistance."],q:"According to the passage, what is the main advantage of the locust's antennae over synthetic sensors?"},{answer:0,options:["Surface-enhanced Raman spectroscopy","Magnetic resonance imaging","Polymerase chain reaction","X-ray crystallography"],q:"The plasmonic foam enables which technique?"},{answer:1,options:["Carbon monoxide","TNT","Methane","Chlorine"],q:"In the tests, the biohybrid system successfully detected the chemical signature of:"},{answer:2,options:["It completely disabled the insect's sense of smell.","It interfered with the insect's movement.","It did not interfere with the insect's other functions.","It shortened the insect's lifespan significantly."],q:"What did the researchers find regarding the foam's effect on the locust's normal functions?"},{answer:0,options:["True","False","Not Given"],q:"The foam attached to the antenna helps researchers identify particular chemical species that the locust alone might not distinguish."},{answer:2,options:["True","False","Not Given"],q:"The biohybrid sensors have already been deployed at airport security checkpoints."},{answer:0,options:["True","False","Not Given"],q:"Raman believes the results demonstrate that biological and engineered sensing approaches can be successfully combined."},{answer:1,options:["Synthetic sensors are superior to biological ones in all respects.","A hybrid of locust antennae and nanomaterials outperforms either approach alone in chemical detection.","Nanomaterials can replace insects in all sensing applications.","Locusts are naturally capable of detecting explosives without modification."],q:"Which of the following best summarises the passage?"}],source:"Phys.org, 20 October 2026 (research published in Advanced Materials, 2026)",title:"When Insects Become Sensors: The Rise of Biohybrid Chemical Detectors"},{notes:[{meaning:"加速；加快",pos:"v./n.",word:"accelerate"},{meaning:"临界点；引爆点",pos:"n.",word:"tipping point"},{meaning:"珊瑚礁",pos:"n.",word:"coral reef"},{meaning:"不可逆转的",pos:"adj.",word:"irreversible"},{meaning:"调节；缓和",pos:"v.",word:"moderate"},{meaning:"崩溃；瓦解",pos:"n./v.",word:"collapse"},{meaning:"强化；加剧",pos:"v.",word:"intensify"},{meaning:"（使）恢复；复原",pos:"v./n.",word:"resilience"},{meaning:"综合的；一体化的",pos:"adj.",word:"integrated"},{meaning:"议程；议事日程",pos:"n.",word:"agenda"},{meaning:"脱碳；减少碳排放",pos:"v.",word:"decarbonise"},{meaning:"生物多样性",pos:"n.",word:"biodiversity"},{meaning:"储备；储量",pos:"n.",word:"reserve"},{meaning:"游说",pos:"v./n.",word:"lobby"},{meaning:"分阶段淘汰",pos:"v.",word:"phase out"},{meaning:"内燃机",pos:"n.",word:"internal combustion engine"},{meaning:"补贴",pos:"n.",word:"subsidy"},{meaning:"破坏；削弱",pos:"v.",word:"undermine"}],passage:`Global warming driven by fossil fuel emissions is not merely continuing — it is accelerating, pushing many of the Earth's most important ecosystems towards the brink. That was the stark warning delivered by Johan Rockström, director of the Potsdam Institute for Climate Impact Research, at the Reuters Sustainability Europe conference in London on Tuesday, just weeks before the United Nations' COP31 climate talks open on 9 November.

Rockström told delegates that damage to coral reefs and the Amazon rainforest was approaching a point where it could become irreversible. Even parts of the Atlantic Ocean circulation system — including the current that carries warm water from the Caribbean and moderates Western Europe's climate — were close to collapse, he said. These systems are among the planet's critical tipping points: thresholds beyond which change becomes self-reinforcing and cannot be undone.

To understand why Rockström's warning carries such weight, it helps to grasp what scientists mean by a tipping point. Most environmental change is gradual: a little more warming produces a little more damage. A tipping point breaks this pattern. Once crossed, the change becomes self-reinforcing — a forest that once absorbed carbon begins to release it as trees die, or melting ice exposes darker water that absorbs still more heat. The system then continues to deteriorate even if the original pressure is removed. Coral reefs, which support a quarter of all marine life despite covering a tiny fraction of the ocean floor, are acutely sensitive to even small rises in sea temperature; prolonged heat causes the corals to expel the symbiotic algae that sustain them, leaving behind bleached skeletons. The Amazon, meanwhile, generates much of its own rainfall through the moisture its trees release into the air — a cycle that begins to fail as deforestation and drought thin the forest canopy.

The latest science, Rockström added, confirms that the world is on course to exceed a 1.5 degree Celsius rise in average surface temperature within the next few years. Such a rise would intensify the frequency and severity of extreme weather events, from prolonged heatwaves to devastating floods, placing ever greater strain on communities and economies alike.

The 1.5 degree threshold Rockström referenced has become the defining benchmark of international climate policy. Adopted as an aspirational goal in the 2015 Paris Agreement, it was chosen because beyond it the risks of crossing multiple tipping points rise sharply. Exceeding it does not mean an overnight catastrophe, but it does mean entering a zone where extreme weather becomes markedly more frequent and where the margin for reversing course narrows with each passing year. For the delegates gathering at COP31 in November, Rockström's intervention sets an uncomfortable agenda: pledges made in conference halls must now be matched by the far harder work of rewiring energy systems, reforming subsidies, and defending the natural systems that ultimately underwrite human prosperity.

Addressing business leaders, Rockström argued that companies preparing for this future should treat climate and nature as a single integrated agenda rather than managing them separately. While continuing to prioritise efforts to decarbonise their operations, firms should also invest in preserving nature — particularly projects aimed at rebuilding biodiversity and protecting reserves of fresh water, both of which buffer societies against climate shocks.

He reserved his sharpest criticism for political backsliding. Rockström said it was "incredibly disturbing" to witness lobbying for an easing of regulations designed to phase out internal combustion engine vehicles. Subsidies for petrol and diesel, he argued, were actively undermining consumer demand for electric vehicles at precisely the moment when momentum needed to accelerate. The message was unambiguous: the science is clear, the risks are compounding, and delay is no longer a neutral choice — it is a decision whose costs will be measured in ecosystems lost and lives disrupted.`,questions:[{answer:1,options:["It is stabilising at current levels.","It is accelerating.","It has begun to reverse.","It is unrelated to fossil fuel emissions."],q:"According to Rockström, what is happening to global warming?"},{answer:2,options:["The Arctic ice cap","Coral reefs and the Amazon rainforest","The Sahara desert","The Himalayan glaciers"],q:"Which ecosystems did Rockström say are close to irreversible damage?"},{answer:0,options:["True","False","Not Given"],q:"Rockström believes the Atlantic current that moderates Western Europe's climate is close to collapse."},{answer:1,options:["True","False","Not Given"],q:"According to the passage, Rockström said companies should handle climate and nature as entirely separate issues."},{answer:0,options:["True","False","Not Given"],q:"Rockström criticised subsidies for petrol and diesel for undermining demand for electric vehicles."},{answer:2,options:["True","False","Not Given"],q:"The passage states that COP31 will be held in London."},{answer:2,options:["Scientists disagree about whether global warming is occurring.","Global warming is accelerating, threatening ecosystems, and Rockström urges integrated action while criticising policy backsliding.","Electric vehicles have solved the climate crisis.","Coral reefs have already fully recovered."],q:"Which of the following best summarises the passage?"}],source:"Reuters, 20 October 2026 (via Northland News Radio)",title:"A Planet Warming Faster: Scientists Warn of Accelerating Climate Change"},{notes:[{meaning:"人工耳蜗；耳蜗植入物",pos:"n.",word:"cochlear implant"},{meaning:"突破性的；开创性的",pos:"adj.",word:"groundbreaking"},{meaning:"提名",pos:"v.",word:"nominate"},{meaning:"可升级的",pos:"adj.",word:"upgradeable"},{meaning:"固件",pos:"n.",word:"firmware"},{meaning:"范式；模式",pos:"n.",word:"paradigm"},{meaning:"声音处理器",pos:"n.",word:"sound processor"},{meaning:"植入的",pos:"adj.",word:"implanted"},{meaning:"有前途的；大有希望的",pos:"adj.",word:"promising"},{meaning:"听力学家",pos:"n.",word:"audiologist"},{meaning:"校准；调整",pos:"v.",word:"calibrate"},{meaning:"精细的；细致的",pos:"adj.",word:"intricate"},{meaning:"刺激",pos:"v./n.",word:"stimulate"},{meaning:"听觉神经",pos:"n.",word:"auditory nerve"},{meaning:"普及；采用",pos:"n.",word:"adoption"},{meaning:"无缝的；顺畅的",pos:"adj.",word:"seamless"},{meaning:"迭代",pos:"n.",word:"iteration"},{meaning:"接受者；受益人",pos:"n.",word:"recipient"}],passage:`For the millions of people worldwide who rely on cochlear implants to hear, technological progress has traditionally arrived through the device worn behind the ear. The internal implant — the component placed surgically inside the head — has remained essentially fixed from the day of the operation. A newly recognised innovation promises to change that paradigm, bringing the concept of the software update to the implant itself.

Cochlear Limited, a global leader in implantable hearing solutions, announced this week that its Nucleus Nexa System has been named one of TIME's Best Inventions of 2026. Described as the world's first and only smart cochlear implant system, the Nexa platform was nominated by TIME's editors, who solicited nominations from correspondents around the world alongside direct applications, paying particular attention to growing fields such as health care and artificial intelligence.

The core breakthrough lies in the implant's upgradeable firmware. Traditionally, innovation in cochlear implants has been delivered almost entirely through the external sound processor, while the implanted component remained unchanged after surgery. The Nexa System breaks with this constraint by building smart, upgradeable technology directly into the implant. Future advances in signal processing can therefore be delivered through both the implant and the sound processor, rather than the external unit alone.

According to Dig Howitt, CEO and President of Cochlear, the system was designed from the outset not merely for the technology of today but for the possibilities of tomorrow. By allowing the implanted hardware to evolve, the platform opens up new possibilities for how cochlear implant technology can develop over time — a shift Howitt described as a source of considerable pride for the company, and, more importantly, of promising benefits for recipients in the years ahead.

Hearing loss is among the most common sensory disabilities in the world, affecting hundreds of millions of people and often isolating them from education, work, and social life. For those with severe to profound sensorineural hearing loss, conventional hearing aids — which depend on residual function in the inner ear — offer limited help, making cochlear implants the only viable path to perceiving sound. Yet the decision to undergo implantation has always carried a quiet compromise: the internal device, once placed, could not keep pace with the rapid evolution of digital signal processing happening outside the body. Each generation of external processor brought clearer sound, but the implant's own capabilities remained frozen in time. The Nexa platform removes that compromise, aligning the lifespan of the implanted hardware with the far faster rhythm of software innovation.

The significance of the advance becomes clearer when one considers how a cochlear implant works. Unlike a hearing aid, which simply amplifies sound, a cochlear implant bypasses damaged parts of the inner ear and directly stimulates the auditory nerve with electrical signals. The external processor captures sound and converts it into digital instructions; the implant then translates those instructions into the intricate patterns of stimulation the brain learns to interpret as hearing. Improvements to either half of this chain can sharpen what a recipient perceives — which is why making the implanted half upgradeable matters so much.

For recipients, the practical implications are substantial. Children implanted at a young age may use the same internal device for decades; an upgradeable implant means they can benefit from each new iteration of processing technology without additional surgery. Audiologists, too, gain finer tools for calibrating devices to individual needs. Wider adoption of such platforms could accelerate a virtuous cycle: as the installed base of smart implants grows, the incentive to develop ever more sophisticated processing algorithms grows with it.

The recognition by TIME places the Nexa System among the year's most celebrated innovations — a reminder that some of the most transformative technologies are not the ones that dazzle on a stage, but the ones that quietly extend human capability. For those whose world was once silent, an implant that can keep learning may mean a lifetime of hearing that keeps getting better.`,questions:[{answer:2,options:["Through the internal implant's firmware","Solely through the external sound processor","Through the battery compartment","Through a separate remote control"],q:"Traditionally, how has innovation in cochlear implants been delivered?"},{answer:1,options:["It is the cheapest cochlear implant available.","It is the first smart cochlear implant system with upgradeable firmware in the implant itself.","It requires no surgery at all.","It was developed by TIME magazine."],q:"What makes the Nucleus Nexa System distinctive?"},{answer:0,options:["True","False","Not Given"],q:"TIME's editors nominated the Nexa System for consideration for the 2026 Best Inventions list."},{answer:1,options:["True","False","Not Given"],q:"According to the passage, a cochlear implant works by simply amplifying sound like a hearing aid."},{answer:0,options:["True","False","Not Given"],q:"An upgradeable implant could allow recipients to benefit from new technology without further surgery."},{answer:2,options:["True","False","Not Given"],q:"The passage states that the Nexa System is already used by more than one million people."},{answer:1,options:["Cochlear implants are becoming obsolete.","The Nexa System's upgradeable implant represents a paradigm shift that could improve recipients' hearing over a lifetime.","TIME magazine manufactures medical devices.","Hearing aids are superior to cochlear implants in every case."],q:"Which of the following best summarises the passage?"}],source:"Cochlear Limited press release via PR Newswire, 20 October 2026",title:"The Implant That Learns: A New Era for Cochlear Technology"}],me={date:L,newsReadings:U},ge=Object.freeze(Object.defineProperty({__proto__:null,date:L,default:me,newsReadings:U},Symbol.toStringTag,{value:"Module"})),ue=["2026-10-21","2026-10-20","2026-10-19"],pe={dates:ue},fe={class:"mx-auto max-w-3xl px-4 pt-6 2xl:px-0"},we={class:"mb-6 flex items-center justify-between"},ye=s("h2",{class:"text-2xl font-bold text-gray-900 dark:text-white"}," 📅 每日阅读 ",-1),be={key:0,class:"rounded-2xl border border-gray-200 bg-white p-12 text-center shadow-sm dark:border-gray-700 dark:bg-gray-800"},ve=s("p",{class:"text-4xl mb-4"}," 🌙 ",-1),ke=s("p",{class:"text-lg text-gray-600 dark:text-gray-300"}," 暂无每日阅读，明早8点见 ",-1),xe=[ve,ke],Te={class:"mb-6"},_e=s("label",{class:"mb-2 block text-sm font-medium text-gray-600 dark:text-gray-400"},"选择日期",-1),Ae=["value"],Ie={key:0,class:"mb-8"},Se=s("h3",{class:"mb-4 text-lg font-bold text-gray-900 dark:text-white"},[v(" 📖 词汇阅读 "),s("span",{class:"ml-2 text-sm font-normal text-gray-500 dark:text-gray-400"},"基于你昨天学过的单词")],-1),qe={id:"reading-vocab",class:"scroll-mt-20 rounded-2xl border border-gray-200 bg-white p-6 shadow-sm dark:border-gray-700 dark:bg-gray-800"},Ce={class:"mb-3 text-xl font-bold text-gray-900 dark:text-white"},je={key:0,class:"mb-4 flex flex-wrap gap-2"},Ne={class:"mb-4 space-y-4 text-gray-700 leading-relaxed dark:text-gray-300"},$e=["innerHTML"],Oe={key:1,class:"mb-4 rounded-xl bg-gray-50 p-4 dark:bg-gray-900/50"},Fe=s("p",{class:"mb-2 text-sm font-bold text-gray-700 dark:text-gray-300"},[v(" 生词注释 "),s("span",{class:"font-normal text-gray-400"},"（点击单词查看中文）")],-1),Re={class:"space-y-1.5"},Me=["onClick"],We={key:0,class:"ml-1.5 text-xs text-gray-400 dark:text-gray-500"},Ge=["onClick"],Be={key:1,class:"ml-1 italic text-gray-500 dark:text-gray-400",style:{"font-family":"times"}},Ee={key:2,class:"ml-2 text-gray-600 dark:text-gray-400"},He={key:2,class:"space-y-4"},Pe={class:"mb-3 text-sm font-medium text-gray-800 dark:text-gray-200"},ze={class:"space-y-2"},De=["onClick"],Le